function trCore(s, depth){
  if(depth>6) return s; const d=depth+1;
  const e=EN[s]; if(e!==undefined) return e;
  for(const [re,f] of ENRX){ const m=re.exec(s); if(m) return f(...m); }
  let m;
  if((m=/^„([\s\S]+)”([.,:;!?]*)$/.exec(s))) return '“'+trCore(m[1],d)+'”'+m[2];
  if((m=/^\(([^()]+)\)$/.exec(s))) return '('+trCore(m[1],d)+')';
  if((m=/^([\s\S]+) \(([^()]+)\)$/.exec(s))){ const a=trCore(m[1],d), b=trCore(m[2],d); if(a!==m[1]||b!==m[2]) return a+' ('+b+')'; }
  if((m=/^([^\p{L}\d„(]+)([\p{L}\d„(][\s\S]*)$/u.exec(s)) && m[1].trim()){ const r=trCore(m[2],d); if(r!==m[2]) return m[1]+r; }
  if((m=/^([\s\S]+?)([.:!?…]+)$/.exec(s))){ const r=trCore(m[1],d); if(r!==m[1]) return r+m[2]; }
  if(/ – | · /.test(s)){ const parts=s.split(/( – | · )/); const out=parts.map((p,i)=>i%2?p:trCore(p,d)).join(''); if(out!==s) return out; }
  return s;
}
function trText(s){
  if(!isEN() || s==null) return s; s=String(s);
  const m=/^(\s*)([\s\S]*?)(\s*)$/.exec(s); if(!m[2]) return s;
  const r=trCore(m[2],0); return r===m[2] ? s : m[1]+r+m[3];
}
const TR_SKIP = new Set(['TEXTAREA','SCRIPT','STYLE','DATALIST']);
const TR_ATTRS = ['placeholder','title','aria-label'];
function trEl(el){ for(const a of TR_ATTRS){ const v=el.getAttribute(a); if(v){ const t=trText(v); if(t!==v) el.setAttribute(a,t); } } }
function trTN(n){ const p=n.parentNode; if(!p || TR_SKIP.has(p.nodeName)) return; const v=n.nodeValue, t=trText(v); if(t!==v) n.nodeValue=t; }
function trTree(root){
  if(!isEN() || !root) return;
  if(root.nodeType===3){ trTN(root); return; }
  if(root.nodeType!==1) return;
  if(TR_SKIP.has(root.tagName)){ if(root.tagName==='TEXTAREA') trEl(root); return; }
  trEl(root);
  const w=document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT, {acceptNode:n=>{ if(n.nodeType===1 && TR_SKIP.has(n.tagName)){ if(n.tagName==='TEXTAREA') trEl(n); return NodeFilter.FILTER_REJECT; } return NodeFilter.FILTER_ACCEPT; }});
  let n; while((n=w.nextNode())){ if(n.nodeType===3) trTN(n); else trEl(n); }
}
const ORIG = {};
function startI18n(){
  ORIG.foot=$('.foot').innerHTML; ORIG.brand=$('.brand').innerHTML;
  new MutationObserver(ms=>{ if(!isEN()) return; for(const m of ms){ if(m.type==='characterData') trTN(m.target); else m.addedNodes.forEach(trTree); } })
    .observe(document.body,{childList:true,subtree:true,characterData:true});
  if(isEN()) trTree(document.body);
}
